targets.query:
from(bucket: "${TESTZONE_INFLUX_BUCKET}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "testzone_run_live" and r._field == "requestRate" and r.run_id == "${run_id}")

from(bucket: "${TESTZONE_INFLUX_BUCKET}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "testzone_run_live" and r._field == "errorRate" and r.run_id == "${run_id}")

from(bucket: "${TESTZONE_INFLUX_BUCKET}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "testzone_run_live" and r._field == "vus" and r.run_id == "${run_id}")
